def solve(rows):
    state = 0
    kept = []
    for i, row in enumerate(rows):
        weight = 0
        if isinstance(row, int):
            weight = row
        elif isinstance(row, str) and row.startswith("|") and row.endswith("|"):
            weight = int(row[1:-1])
        elif isinstance(row, list):
            for item in row:
                if isinstance(item, int):
                    weight += item
                elif isinstance(item, str):
                    weight += len(item)

        if (state + weight + i) % 7 != 3 or i == len(rows) - 1:
            kept.append(row)

        if weight == 0:
            state = 0
        else:
            state = (3 * state + weight) % 7

    if not kept:
        return []

    final_state = state
    kept_length = len(kept)
    rotation = final_state % kept_length
    rotated_kept = kept[rotation:] + kept[:rotation]

    expiry_days = []
    for row in rotated_kept:
        if len(row) == 2 and isinstance(row[0], int) and isinstance(row[1], int):
            day = row[0]
            lifetime = row[1]
            expiry_day = day + lifetime
            while expiry_day % 7 == 5 or expiry_day % 7 == 6:
                expiry_day += 1
            expiry_days.append(expiry_day)

    return expiry_days

